sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var payload = current.getValue('payload');
        if (!payload) {
            gs.info('[iQube - Treasury]:Business Rule = Data Processing Treasury Static Data MRD | No payload found on record ' + current.getDisplayValue());
            return;
        }

        var data = JSON.parse(payload);

        var treasuryTeamId = '';
        var preAdviseFlag = '';
        var accountingSystem = '';
        if (data.account && data.account.otherAccountDetails && data.account.otherAccountDetails.otherDetails) {
            var otherDetails = data.account.otherAccountDetails.otherDetails;
            if (!Array.isArray(otherDetails)) otherDetails = [otherDetails];
            for (var j = 0; j < otherDetails.length; j++) {
                var name = otherDetails[j].fieldName;
                var val = otherDetails[j].fieldValue;
                if (name == 'TreasuryTeamId') {
                    treasuryTeamId = val;
                } else if (name == 'PreAdviseFlag') {
                    preAdviseFlag = val;
                } else if (name == 'AccountingAndValuationSystemIdentification') {
                    accountingSystem = val; // e.g., MULTIFONDS or IMS
                }
            }
        }

        var securitiesAccountNumber = '';
        var fundId = '';
        if (data.account && data.account.accountAlternateIdentifiers && data.account.accountAlternateIdentifiers.accountAlternateIdentifier) {
            var altIds = data.account.accountAlternateIdentifiers.accountAlternateIdentifier;
            if (!Array.isArray(altIds)) altIds = [altIds];
            for (var i = 0; i < altIds.length; i++) {
                if (altIds[i].identifierName == 'SecuritiesAccountNumber') {
                    securitiesAccountNumber = altIds[i].identifierValue;
                }

                // FundId (AccountId) based on accounting system
                else if (!fundId && altIds[i].identifierName === 'AccountId') {
                    if (altIds[i].sourceSystemName === accountingSystem) {
                        fundId = altIds[i].identifierValue;
                    }
                }

				else if (securitiesAccountNumber && fundId) break;
            }
        }

        var treasuryMakerCode = '';
        if (data.account && data.account.staffRoles && data.account.staffRoles.staffRole) {
            var staffRoles = data.account.staffRoles.staffRole;
            if (!Array.isArray(staffRoles)) staffRoles = [staffRoles];
            for (var k = 0; k < staffRoles.length; k++) {
                if (staffRoles[k].roleName && staffRoles[k].roleName.value == 'TreasuryMaker') {
                    treasuryMakerCode = staffRoles[k].roleValue.value;
                    break;
                }
            }
        }

        var clientGroup = '';
        if (data.account && data.account.accountClientGroupings && data.account.accountClientGroupings.accountClientGrouping) {
            var groupings = data.account.accountClientGroupings.accountClientGrouping;
            if (!Array.isArray(groupings)) groupings = [groupings];
            for (var l = 0; l < groupings.length; l++) {
                if (groupings[l].groupingName && groupings[l].groupingName.value == 'ClientGroup') {
                    clientGroup = groupings[l].groupingValue.value;
                    break;
                }
            }
        }

        var staticDataGR = new GlideRecord('x_hsb11_mss_tsd_treasury_static_data');
        staticDataGR.addQuery('tsd_code', securitiesAccountNumber);
        staticDataGR.query();
        if (staticDataGR.next()) {
            staticDataGR.team_id = treasuryTeamId;
            staticDataGR.task_owner = treasuryMakerCode;
            staticDataGR.client_group = clientGroup;
			staticDataGR.fund_id = fundId;
			staticDataGR.preadviseflag = preAdviseFlag;
            staticDataGR.active = true;
            staticDataGR.update();
            gs.info('[iQube - Treasury]:Business Rule = Data Processing Treasury Static Data MRD | Static data updated for inbound record: ' + current.getDisplayValue());
        } else {
            staticDataGR.initialize();
            staticDataGR.tsd_code = securitiesAccountNumber;
            staticDataGR.team_id = treasuryTeamId;
            staticDataGR.task_owner = treasuryMakerCode;
            staticDataGR.client_group = clientGroup;
			staticDataGR.fund_id = fundId;
			staticDataGR.preadviseflag = preAdviseFlag;
            staticDataGR.active = true;
            staticDataGR.insert();
            gs.info('[iQube - Treasury]:Business Rule = Data Processing Treasury Static Data MRD | Static data inserted for inbound record: ' + current.getDisplayValue());
        }
    } catch (e) {
        gs.error('[iQube - Treasury]: Error in Business Rule = Data Processing Treasury Static Data MRD | x_hsb11_hsbc_mss_o_mss_widget_inbound: ' + e.message);
        new x_hsb11_mss_tsd.MSS_Treasury_XMatter_ITID_WidgetFailureHandler().createITIDEvent("MINOR", '[iQube - Treasury]: Error in Business Rule = Data Processing Treasury Static Data MRD | x_hsb11_hsbc_mss_o_mss_widget_inbound: ' + e.message, 'MSSiQubeSN');
    }
})(current, previous);
